// Intake record guard: flags intake records a dispatcher cannot act on.
// Built for the Dispatch Kit intake schema; works for any record with these field names.
const PLACEHOLDERS = new Set([
  "", "unknown", "n/a", "na", "none", "null", "tbd", "not provided", "not given",
  "123 main st", "123 main street", "555-555-5555", "5555555555", "(555) 555-5555",
  "john doe", "jane doe", "test", "example",
]);
const URGENCY = ["emergency", "same_day", "routine"];

// A field counts only if a dispatcher could act on it. Nulls, blanks and
// placeholders like "unknown" or "123 Main St" do not count.
function captured(v) {
  if (v === null || v === undefined) return false;
  if (typeof v === "string") return !PLACEHOLDERS.has(v.trim().toLowerCase());
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === "object") return Object.values(v).some(captured);
  return true;
}

function address(a) {
  if (!a || typeof a !== "object") return "(none)";
  const parts = [a.street, a.unit, a.city, a.state, a.postal_code].filter(captured);
  return parts.length ? parts.join(", ") : "(none)";
}

return $input.all().map((item) => {
  // Accept the record as the whole request body, or wrapped as { "record": { ... } }.
  const body = item.json.body ?? item.json;
  const r = (body && body.record) ? body.record : (body || {});
  const problems = [];

  if (r.schema_version === undefined) {
    problems.push("no schema_version, so this may not be an intake record at all");
  }
  if (!URGENCY.includes(r.urgency)) {
    problems.push(`urgency is ${JSON.stringify(r.urgency)}, expected one of: ${URGENCY.join(", ")}`);
  }
  const reachable = captured(r.callback_number);
  const locatable = captured(r.service_address);
  if (!reachable) problems.push("no usable callback_number");
  if (!locatable) problems.push("no usable service_address");
  if (!captured(r.problem_summary)) problems.push("no problem_summary");

  const emergency = r.urgency === "emergency";
  const unreachable = emergency && (!reachable || !locatable);

  // Every emergency reaches a human now. An emergency nobody can act on is the worst case.
  let severity = "ok";
  if (emergency) severity = "page";
  else if (problems.length) severity = "review";

  const summary = captured(r.problem_summary) ? r.problem_summary : "(no summary)";
  let alert_text;
  if (unreachable) {
    alert_text =
      `[PAGE] EMERGENCY (${r.emergency_type || "type not set"}) with no way to act on it. ` +
      `Missing: ${[!reachable && "callback number", !locatable && "address"].filter(Boolean).join(" and ")}. ` +
      `Pull the caller ID from your phone platform and call back now. Summary: ${summary}`;
  } else if (emergency) {
    alert_text =
      `[PAGE] Emergency (${r.emergency_type || "type not set"}) at ${address(r.service_address)}. ` +
      `Call back: ${r.callback_number}. Summary: ${summary}`;
  } else if (severity === "review") {
    alert_text = `[REVIEW] Intake record needs a human: ${problems.join("; ")}. Summary: ${summary}`;
  } else {
    alert_text = "";
  }

  return { json: { severity, unreachable, problems, alert_text, record: r } };
});
